import std/io (println)
import std/string (chars)

-- Recursively walk the character list, tracking parenthesis depth.
-- Fail fast if depth drops below zero; balanced iff depth ends at 0.
func walk(cs: [string], depth: int) -> bool =
  match cs {
    [] => depth == 0,
    c :: rest =>
      if depth < 0 then false
      else if c == "(" then walk(rest, depth + 1)
      else if c == ")" then walk(rest, depth - 1)
      else walk(rest, depth)
  }

export func isBalanced(s: string) -> bool = walk(chars(s), 0)

export func main() -> () ! {IO} {
  println(show(isBalanced("(())")));
  println(show(isBalanced("(()")));
  println(show(isBalanced("())()")));
  println(show(isBalanced("()(())")))
}

