import std/io (println)

type Mat3 = {
  m00: int, m01: int, m02: int,
  m10: int, m11: int, m12: int,
  m20: int, m21: int, m22: int
}

pure func modVal() -> int = 1000000007

pure func idMat() -> Mat3 = {
  m00: 1, m01: 0, m02: 0,
  m10: 0, m11: 1, m12: 0,
  m20: 0, m21: 0, m22: 1
}

pure func baseMat() -> Mat3 = {
  m00: 1, m01: 0, m02: 1,
  m10: 1, m11: 1, m12: 0,
  m20: 0, m21: 1, m22: 0
}

pure func mul(a: Mat3, b: Mat3) -> Mat3 {
  let m = modVal();
  {
    m00: (a.m00 * b.m00 + a.m01 * b.m10 + a.m02 * b.m20) % m,
    m01: (a.m00 * b.m01 + a.m01 * b.m11 + a.m02 * b.m21) % m,
    m02: (a.m00 * b.m02 + a.m01 * b.m12 + a.m02 * b.m22) % m,
    m10: (a.m10 * b.m00 + a.m11 * b.m10 + a.m12 * b.m20) % m,
    m11: (a.m10 * b.m01 + a.m11 * b.m11 + a.m12 * b.m21) % m,
    m12: (a.m10 * b.m02 + a.m11 * b.m12 + a.m12 * b.m22) % m,
    m20: (a.m20 * b.m00 + a.m21 * b.m10 + a.m22 * b.m20) % m,
    m21: (a.m20 * b.m01 + a.m21 * b.m11 + a.m22 * b.m21) % m,
    m22: (a.m20 * b.m02 + a.m21 * b.m12 + a.m22 * b.m22) % m
  }
}

pure func matPow(m: Mat3, p: int) -> Mat3 =
  if p == 0 then idMat()
  else if p == 1 then m
  else if p % 2 == 0 then {
    let half = matPow(m, p / 2);
    mul(half, half)
  } else {
    let half = matPow(m, p / 2);
    mul(m, mul(half, half))
  }

pure func countNo101(n: int) -> int {
  let mn = matPow(baseMat(), n);
  (mn.m00 + mn.m10 + mn.m20) % modVal()
}

export func main() -> () ! {IO} {
  println(show(countNo101(1000000000000000000)));
  println(show(countNo101(987654321987654321)))
}

