  -- Leaf(0) stands in for an absent child and contributes nothing to the sum.
  let tree = Node(Node(Leaf(1), 3, Leaf(4)), 5, Node(Leaf(0), 8, Leaf(10)));
  println(show(treeSum(tree)))
}

