import std/string (split, length)
import std/list (length as listLength)
import std/option (Option, Some, None)
import std/result (Result, Ok, Err)

func validateVersion(version: string) -> bool {
  let parts = split(version, ".");
  listLength(parts) == 3
}

func validatePort(port: int) -> bool =
  port >= 1024 && port <= 65535

func loadConfig(path: string) -> Result[string, string] ! {FS} {
  let content = readFile(path);
  match decode(content) {
    Ok(json) => {
      let appName = match getString(json, "app_name") {
        Some(n) => n,
        None => ""
      };
      let version = match getString(json, "version") {
        Some(v) => v,
        None => ""
      };
      let port = match getInt(json, "port") {
        Some(p) => p,
        None => 0
      };
      let features = match getArray(json, "features") {
        Some(f) => f,
        None => []
      };
      if not validatePort(port) then Err("Invalid port")
      else if not validateVersion(version) then Err("Invalid version")
      else if listLength(features) == 0 then Err("No features")
      else Ok("Loaded ${appName} v${version} on port ${show(port)} with ${show(listLength(features))} features")
    },
    Err(msg) => Err("Parse error: ${msg}")
  }
}

func createConfig() -> () ! {FS} {
  let json = "{\"app_name\":\"MyApp\",\"version\":\"1.0.0\",\"port\":8080,\"features\":[\"logging\",\"auth\",\"api\"]}";
  writeFile("app_config.json", json)
}

export func main() -> () ! {IO, FS} {
  createConfig();
  match loadConfig("app_config.json") {
    Ok(msg) => println(msg),
    Err(msg) => println("Error: ${msg}")
  }
}

