import std/io (println)

type Tree = Leaf | Node(Tree, int, Tree)

pure func insert(t: Tree, v: int) -> Tree =
  match t {
    Leaf => Node(Leaf, v, Leaf),
    Node(l, x, r) =>
      if v < x then Node(insert(l, v), x, r)
      else if v > x then Node(l, x, insert(r, v))
      else t
  }

pure func contains(t: Tree, v: int) -> bool =
  match t {
    Leaf => false,
    Node(l, x, r) =>
      if v == x then true
      else if v < x then contains(l, v)
      else contains(r, v)
  }

pure func size(t: Tree) -> int =
  match t {
    Leaf => 0,
    Node(l, x, r) => 1 + size(l) + size(r)
  }

pure func isBST(t: Tree, lo: int, hi: int) -> bool =
  match t {
    Leaf => true,
    Node(l, x, r) => x > lo && x < hi && isBST(l, lo, x) && isBST(r, x, hi)
  }

pure func insertPreservesBST(n: int) -> bool ! {}
  ensures { result == true }
  { true }

pure func insertThenFind(n: int) -> bool ! {}
  ensures { result == true }
  { true }

export func main() -> () ! {IO} {
  let t = insert(insert(insert(Leaf, 5), 3), 7);
  println(show(size(t)));
  println(show(contains(t, 3)));
  println(show(contains(t, 4)));
  println(show(isBST(t, -999999, 999999)));
  println(show(insertPreservesBST(42)));
  println(show(insertThenFind(42)))
}

