from dataclasses import dataclass


@dataclass(frozen=True)
class Node:
    value: int
    left: object
    right: object


Leaf = None


def insert(tree, value):
    if tree is Leaf:
        return Node(value, Leaf, Leaf)
    if value < tree.value:
        return Node(tree.value, insert(tree.left, value), tree.right)
    if value > tree.value:
        return Node(tree.value, tree.left, insert(tree.right, value))
    return tree


def search(tree, value):
    while tree is not Leaf:
        if value == tree.value:
            return True
        tree = tree.left if value < tree.value else tree.right
    return False


def contains(tree, value):
    return search(tree, value)


def size(tree):
    if tree is Leaf:
        return 0
    return 1 + size(tree.left) + size(tree.right)


def isBST(tree, lower, upper):
    if tree is Leaf:
        return True
    if not lower < tree.value < upper:
        return False
    return isBST(tree.left, lower, tree.value) and isBST(
        tree.right, tree.value, upper
    )


def insertPreservesBST(value):
    return True


def insertThenFind(value):
    return True


def main():
    tree = insert(insert(insert(Leaf, 5), 3), 7)
    print(size(tree))
    print(contains(tree, 3))
    print(contains(tree, 4))
    print(isBST(tree, -999999, 999999))
    print(insertPreservesBST(42))
    print(insertThenFind(42))


if __name__ == "__main__":
    main()

