module benchmark/solution

import std/string (chars, repeat, stringToInt)
import std/list (drop)
import std/option (getOrElse)

func isDigit(c: string) -> bool =
  c == "0" || c == "1" || c == "2" || c == "3" || c == "4" ||
  c == "5" || c == "6" || c == "7" || c == "8" || c == "9"

func countRun(c: string, cs: [string]) -> int =
  match cs {
    [] => 0,
    h :: t => if h == c then 1 + countRun(c, t) else 0
  }

func encodeChars(cs: [string]) -> string =
  match cs {
    [] => "",
    c :: rest => {
      let n = countRun(c, cs);
      let remaining = drop(n, cs);
      "${show(n)}${c}${encodeChars(remaining)}"
    }
  }

func encode(s: string) -> string =
  encodeChars(chars(s))

func decodeHelper(cs: [string], countStr: string) -> string =
  match cs {
    [] => "",
    h :: t =>
      if isDigit(h) then decodeHelper(t, "${countStr}${h}")
      else {
        let n = getOrElse(stringToInt(countStr), 0);
        "${repeat(h, n)}${decodeHelper(t, "")}"
      }
  }

func decode(s: string) -> string =
  decodeHelper(chars(s), "")

func roundtrip(s: string) -> bool =
  decode(encode(s)) == s

func singleCharEncode(s: string) -> string =
  encode(s)

export func main() -> () ! {IO} {
  println(encode("aaabbc"));
  println(encode("xyz"));
  println(decode("3a2b1c"));
  println(decode("1x1y1z"));
  println(show(roundtrip("hello")));
  println(singleCharEncode("q"))
}

