from typing import Iterator


class SortedSet:
    __slots__ = ()

    def __iter__(self) -> Iterator[int]:
        current = self
        while isinstance(current, SCons):
            yield current.head
            current = current.tail


class _SNil(SortedSet):
    __slots__ = ()

    def __repr__(self) -> str:
        return "SNil"


SNil = _SNil()


@dataclass(frozen=True)
class SCons(SortedSet):
    head: int
    tail: SortedSet = SNil

    def __post_init__(self) -> None:
        if not isinstance(self.head, int):
            raise TypeError("Set elements must be integers.")
        if self.tail is not SNil and not isinstance(self.tail, SCons):
            raise TypeError("The tail must be a sorted integer set.")
        if isinstance(self.tail, SCons) and self.head >= self.tail.head:
            raise ValueError("Set elements must be strictly increasing.")


def _from_sorted(values: list[int]) -> SortedSet:
    result = SNil
    for value in reversed(values):
        result = SCons(value, result)
    return result


def sMerge(a: SortedSet, b: SortedSet) -> SortedSet:
    values = []
    while isinstance(a, SCons) and isinstance(b, SCons):
        if a.head < b.head:
            values.append(a.head)
            a = a.tail
        elif b.head < a.head:
            values.append(b.head)
            b = b.tail
        else:
            values.append(a.head)
            a = a.tail
            b = b.tail

    result = b if a is SNil else a
    for value in reversed(values):
        result = SCons(value, result)
    return result


