type Account = Alice | Bob

type Op =
    Dep(Account, int)
  | Wd(Account, int)
  | Save
  | Commit
  | Restore

type State = {
  alice: int,
  bob: int,
  stack: [{alice: int, bob: int}],
  failures: int
}

func step(st: State, op: Op) -> State {
  match op {
    Dep(acct, amt) =>
      match acct {
        Alice => {st | alice: st.alice + amt},
        Bob => {st | bob: st.bob + amt}
      },
    Wd(acct, amt) => {
      let bal = match acct { Alice => st.alice, Bob => st.bob };
      if bal >= amt then
        match acct {
          Alice => {st | alice: st.alice - amt},
          Bob => {st | bob: st.bob - amt}
        }
      else {
        let newFailures = st.failures + 1;
        match st.stack {
          [] => {st | failures: newFailures},
          snap :: rest => {st | alice: snap.alice, bob: snap.bob, stack: rest, failures: newFailures}
        }
      }
    },
    Save => {
      let snap = {alice: st.alice, bob: st.bob};
      {st | stack: snap :: st.stack}
    },
    Commit =>
      match st.stack {
        [] => {st | failures: st.failures + 1},
        _ :: rest => {st | stack: rest}
      },
    Restore =>
      match st.stack {
        [] => {st | failures: st.failures + 1},
        snap :: rest => {st | alice: snap.alice, bob: snap.bob, stack: rest}
      }
  }
}

func runOps(st: State, ops: [Op]) -> State =
  match ops {
    [] => st,
    op :: rest => runOps(step(st, op), rest)
  }

export func main() -> () ! {IO} {
  let initState = {
    alice: 100,
    bob: 50,
    stack: [],
    failures: 0
  };
  let ops = [
    Save,
    Dep(Alice, 30),
    Save,
    Wd(Bob, 80),
    Wd(Alice, 90),
    Save,
    Wd(Alice, 50),
    Dep(Bob, 25),
    Commit,
    Restore,
    Wd(Bob, 75),
    Commit,
    Dep(Alice, 5)
  ];
  let finalState = runOps(initState, ops);
  println("alice=${show(finalState.alice)}");
  println("bob=${show(finalState.bob)}");
  println("failures=${show(finalState.failures)}")
}

