import sys
from typing import Generic, TypeVar

T = TypeVar("T")


class Result(Generic[T]):
    pass


@dataclass
class Ok(Result[T]):
    value: T


@dataclass
class Err(Result[T]):
    message: str


def validate_age(age: int) -> Result[int]:
    if 0 <= age <= 150:
        return Ok(age)
    return Err("Age out of range")


def calculate_retirement_years(age: int) -> Result[int]:
    if age < 65:
        return Ok(65 - age)
    return Err("Already retired")


def years_to_retirement(age: int) -> Result[int]:
    validated = validate_age(age)
    if isinstance(validated, Err):
        return validated
    return calculate_retirement_years(validated.value)


def main() -> None:
    for value in sys.stdin.read().split():
        result = years_to_retirement(int(value))
        if isinstance(result, Ok):
            print(f"Years to retirement: {result.value}")
        else:
            print(f"Error: {result.message}")


if __name__ == "__main__":
    main()

