        (n, neighbors) =>
          if n == node then neighbors else getNeighbors(node, rest)
      }
  }

func bfsLoop(queue: [int], visited: [int], graph: [(int, [int])]) -> [int] {
  match queue {
    [] => visited,
    curr :: qRest => {
      if contains(curr, visited) then
        bfsLoop(qRest, visited, graph)
      else {
        let newVisited = visited ++ [curr];
        let neighbors = getNeighbors(curr, graph);
        let newQueue = enqueueNeighbors(neighbors, qRest);
        bfsLoop(newQueue, newVisited, graph)
      }
    }
  }
}

