type Term =
    TVar(string)
  | TLam(string, Term)
  | TApp(Term, Term)

func subst(term: Term, varName: string, replacement: Term) -> Term =
  match term {
    TVar(x) => if x == varName then replacement else TVar(x),
    TLam(param, body) =>
      if param == varName then
        TLam(param, body)
      else
        TLam(param, subst(body, varName, replacement)),
    TApp(f, arg) =>
      TApp(subst(f, varName, replacement), subst(arg, varName, replacement))
  }

func eval(term: Term) -> Term =
  match term {
    TVar(x) => TVar(x),
    TLam(param, body) => TLam(param, body),
    TApp(f, arg) => {
      let fVal = eval(f);
      let argVal = eval(arg);
      match fVal {
        TLam(param, body) => eval(subst(body, param, argVal)),
        _ => TApp(fVal, argVal)
      }
    }
  }

