type Tree = Leaf(int) | Node(Tree, int, Tree)

func tree_sum(tree: Tree) -> int =
  match tree {
    Leaf(v) => v,
    Node(l, v, r) => tree_sum(l) + v + tree_sum(r)
  }

func find_max(tree: Tree) -> int =
  match tree {
    Leaf(v) => v,
    Node(Leaf(lv), v, Leaf(rv)) =>
      if lv >= v && lv >= rv then lv
      else if rv >= v then rv
      else v,
    Node(Leaf(lv), v, r) => {
      let mr = find_max(r);
      if lv >= v && lv >= mr then lv
      else if mr >= v then mr
      else v
    },
    Node(l, v, Leaf(rv)) => {
      let ml = find_max(l);
      if ml >= v && ml >= rv then ml
      else if rv >= v then rv
      else v
    },
    Node(l, v, r) => {
      let ml = find_max(l);
      let mr = find_max(r);
      if ml >= v && ml >= mr then ml
      else if mr >= v then mr
      else v
    }
  }

export func main() -> () ! {IO} {
