type Color = Red | Black

type RBTree = Empty | Node(Color, RBTree, int, RBTree)

func balance(color: Color, left: RBTree, value: int, right: RBTree) -> RBTree =
  match color {
    Black => match left {
      Node(Red, Node(Red, a, x, b), y, c) =>
        Node(Red, Node(Black, a, x, b), y, Node(Black, c, value, right)),
      Node(Red, a, x, Node(Red, b, y, c)) =>
        Node(Red, Node(Black, a, x, b), y, Node(Black, c, value, right)),
      _ => match right {
        Node(Red, Node(Red, b, y, c), z, d) =>
          Node(Red, Node(Black, left, value, b), y, Node(Black, c, z, d)),
        Node(Red, b, y, Node(Red, c, z, d)) =>
          Node(Red, Node(Black, left, value, b), y, Node(Black, c, z, d)),
        _ => Node(color, left, value, right)
      }
    },
    Red => Node(color, left, value, right)
  }

func ins(x: int, tree: RBTree) -> RBTree =
  match tree {
    Empty => Node(Red, Empty, x, Empty),
    Node(c, l, v, r) =>
      if x < v then balance(c, ins(x, l), v, r)
      else if x > v then balance(c, l, v, ins(x, r))
      else Node(c, l, v, r)
  }

func insert(x: int, tree: RBTree) -> RBTree =
  match ins(x, tree) {
    Empty => Empty,
    Node(_, l, v, r) => Node(Black, l, v, r)
  }

func inorder(tree: RBTree) -> [int] =
  match tree {
    Empty => [],
    Node(_, l, v, r) => inorder(l) ++ [v] ++ inorder(r)
  }

func insertList(xs: [int], tree: RBTree) -> RBTree =
  match xs {
    [] => tree,
    x :: rest => insertList(rest, insert(x, tree))
  }

