    1 => 125,
    2 => 75,
    3 => 100,
    _ => 0
  }

pure func step(state: State, event: Event) -> Result[State] =
  match state {
    Idle => match event {
      Insert(n) => Ok(HasCredit(n)),
      Select(_) => Err("no_credit"),
      DispenseDone => Err("not_dispensing")
    },
    HasCredit(c) => match event {
      Insert(n) => Ok(HasCredit(c + n)),
      Select(code) => if code < 1 || code > 3 then Err("unknown_item")
                      else if c < price(code) then Err("insufficient_funds")
                      else Ok(Dispensing(c - price(code))),
      DispenseDone => Err("not_dispensing")
    },
    Dispensing(_) => match event {
      Insert(_) => Err("busy"),
      Select(_) => Err("busy"),
      DispenseDone => Ok(Idle)
    }
  }

