  match s {
    Idle => "ok: IDLE",
    HasCredit(n) => "ok: CREDIT(${show(n)})",
    Dispensing(ch) => "ok: DISPENSING(${show(ch)})"
  }

pure func showResult(r: Result[State]) -> string =
  match r {
    Ok(s) => showState(s),
    Err(reason) => "err: ${reason}"
  }

