import std/list (sortBy, take)

func nextLcg(x: int) -> int =
  (48271 * x) % 2147483647

func genStream(count: int, current: int, acc: [int]) -> [int] =
  if count == 0 then acc
  else {
    let nextVal = nextLcg(current);
    genStream(count - 1, nextVal, nextVal :: acc)
  }

func cmpDesc(a: int, b: int) -> int =
  b - a

func sumAcc(xs: [int], acc: int) -> int =
  match xs {
    [] => acc,
    x :: rest => sumAcc(rest, acc + x)
  }

func sumModAcc(xs: [int], acc: int) -> int =
  match xs {
    [] => acc,
    x :: rest => sumModAcc(rest, (acc + x) % 1000000007)
  }

export func main() -> () ! {IO} {
  let stream = genStream(2000, 20260708, []);
  let x2000 = match stream {
    x :: _ => x,
    [] => 0
  };
  let sorted = sortBy(cmpDesc, stream);
  let top10 = take(10, sorted);
  let sumTop10 = sumAcc(top10, 0);
  let totalMod = sumModAcc(stream, 0);
  println(show(x2000));
  println(show(sumTop10));
  println(show(totalMod))
}

