type Type = TVar(string) | TInt | TBool | TFunc(Type, Type)
type UnifyResult = Success([(string, Type)]) | Failure

func apply(subst: [(string, Type)], t: Type) -> Type =
  match t {
    TVar(name) => match lookup(subst, name) {
      Some(value) => apply(subst, value),
      None => TVar(name)
    },
    TInt => TInt,
    TBool => TBool,
    TFunc(arg, result) => TFunc(apply(subst, arg), apply(subst, result))
  }

func lookup(subst: [(string, Type)], name: string) -> Option[Type] =
  match subst {
    [] => None,
    (key, value) :: rest =>
      if key == name then Some(value) else lookup(rest, name)
  }

func unify(t1: Type, t2: Type) -> UnifyResult =
  match t1 {
    TInt => match t2 {
      TInt => Success([]),
      TVar(name) => Success([(name, TInt)]),
      _ => Failure
    },
    TBool => match t2 {
      TBool => Success([]),
      TVar(name) => Success([(name, TBool)]),
      _ => Failure
    },
    TVar(name) => Success([(name, t2)]),
    TFunc(arg1, result1) => match t2 {
      TVar(name) => Success([(name, t1)]),
      TFunc(arg2, result2) => match unify(arg1, arg2) {
        Success(s1) => match unify(apply(s1, result1), apply(s1, result2)) {
          Success(s2) => Success(s1 ++ s2),
          Failure => Failure
        },
        Failure => Failure
      },
      _ => Failure
    }
  }

func showType(t: Type) -> string =
  match t {
    TVar(name) => "TVar(${name})",
    TInt => "TInt",
    TBool => "TBool",
    TFunc(arg, result) => "TFunc(${showType(arg)}, ${showType(result)})"
  }

export func main() -> () ! {IO} {
  let left = TFunc(TVar("a"), TInt);
  let right = TFunc(TBool, TVar("b"));
  match unify(left, right) {
    Success(subst) => {
      match lookup(subst, "a") {
        Some(value) => println("a = ${showType(value)}"),
        None => ()
      };
      match lookup(subst, "b") {
        Some(value) => println("b = ${showType(value)}"),
        None => ()
      }
    },
    Failure => ()
  }
}

